#include "runtime_undo_journal.h"
#include <iostream>
struct Record{int value;inline static size_t copies=0;Record(int n):value(n){}Record(const Record&r):value(r.value){++copies;}Record(Record&&r)noexcept:value(r.value){};};
int main(){try{RuntimeUndoJournal<Record>journal;for(int i=0;i<10000;++i){std::vector<Record>group;group.reserve(3);for(int n=0;n<3;++n)group.emplace_back(i*3+n);journal.appendGroup(std::move(group));}if(Record::copies||journal.undo.size()!=30000)throw std::runtime_error("history copied");int expected=29999;for(int i=0;i<10000;++i)if(journal.reverse([&](const Record&r,bool){if(r.value!=expected--)throw std::runtime_error("undo order");})!=3)throw std::runtime_error("undo boundary");expected=0;for(int i=0;i<10000;++i)if(journal.forward([&](const Record&r,bool){if(r.value!=expected++)throw std::runtime_error("redo order");})!=3)throw std::runtime_error("redo boundary");journal.reverse([](const Record&,bool){});std::vector<Record>next;next.emplace_back(99);journal.appendGroup(std::move(next));if(!journal.redo.empty()||Record::copies)throw std::runtime_error("branch/copy");std::cout<<"undo group append passed groups=10000 records=30000 copies=0 undo_redo_boundaries=passed branch_redo_clear=passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
